// CloudtainerML rev0033 — Directional suppression routing wind tunnel.
// Synthetic probe inspired by Directional Routing in Transformers. Not a reproduction.
#include <bits/stdc++.h>
using namespace std; static string q(const string&s){string o="\""; for(char c:s){if(c=='"'||c=='\\')o+='\\'; if(c=='\n')o+="\\n"; else o+=c;} return o+'"';}
struct Regime{string name; double signal, distractor, head_redundancy, domain_shift, syntactic_fixed, rare_dir, cost_pressure; int seed;};
struct Row{string regime,method; double recall, leakage, coordination, ablation_fragility, cost, rare_miss, regret, score;};
static double C(double x){return max(0.0,min(1.0,x));}
static double j(int seed,const string&m){uint64_t h=0xcbf29ce484222325ULL; for(char c:m){h^=(unsigned char)c;h*=0x100000001b3ULL;} h^=seed*0x9e3779b97f4a7c15ULL; return ((h%1000)/1000.0-.5)*.010;}
static Row eval(const Regime&r,const string&m){double recall=0,leak=0,coord=0,frag=0,cost=0,rare=0; double base=.50+.22*r.signal-.18*r.distractor+.05*r.head_redundancy;
 if(m=="vanilla_heads"){recall=base+.08*r.head_redundancy; leak=.42*r.distractor+.20*r.domain_shift; coord=.18; frag=.22; cost=1.0; rare=.30*r.rare_dir;}
 else if(m=="random_suppression_dirs"){recall=base+.03-.06*r.rare_dir; leak=.32*r.distractor; coord=.24; frag=.34; cost=1.04; rare=.44*r.rare_dir;}
 else if(m=="independent_head_suppression"){recall=base+.10-.04*r.domain_shift; leak=.24*r.distractor; coord=.40+.08*r.head_redundancy; frag=.28+.10*r.domain_shift; cost=1.08; rare=.22*r.rare_dir;}
 else if(m=="shared_directional_router"){recall=base+.17+.08*r.domain_shift+.04*r.syntactic_fixed-.05*r.rare_dir; leak=.16*r.distractor; coord=.78+.10*r.signal; frag=.58-.20*r.head_redundancy; cost=1.11; rare=.18*r.rare_dir;}
 else if(m=="late_fixed_pruner"){recall=base+.05+.16*r.syntactic_fixed-.08*r.domain_shift; leak=.18*r.distractor; coord=.52+.20*r.syntactic_fixed; frag=.36+.18*r.domain_shift; cost=1.03; rare=.26*r.rare_dir;}
 else if(m=="domain_adaptive_then_fixed"){recall=base+.14+.09*r.domain_shift+.10*r.syntactic_fixed-.04*r.rare_dir; leak=.15*r.distractor; coord=.70+.10*r.syntactic_fixed; frag=.42-.10*r.head_redundancy; cost=1.12; rare=.15*r.rare_dir;}
 else if(m=="oracle_directional_router"){recall=base+.28; leak=.05*r.distractor; coord=.95; frag=.18; cost=1.15; rare=.03*r.rare_dir;}
 recall=C(recall+j(r.seed,m)); leak=C(leak); coord=C(coord); frag=C(frag); rare=C(rare); double score=(1-recall)+.42*leak+.22*frag+.22*rare+.12*cost*r.cost_pressure-.10*coord; return {r.name,m,recall,leak,coord,frag,cost,rare,0,score};}
int main(int argc,char**argv){string out=argc>1?argv[1]:"REV0033_DIRECTIONAL_SUPPRESSION_ROUTER_SMOKE.json"; vector<Regime> regs={{"domain_adaptive_signal",.88,.65,.35,.88,.15,.20,.65,1},{"late_syntactic_pruning",.74,.60,.55,.20,.92,.18,.70,2},{"redundant_heads",.80,.48,.92,.30,.35,.15,.90,3},{"rare_suppression_direction",.70,.72,.40,.52,.38,.95,.75,4},{"noisy_induction",.78,.82,.48,.55,.30,.45,.85,5},{"low_overhead_regime",.76,.55,.50,.46,.45,.28,1.30,6}}; vector<string> methods={"vanilla_heads","random_suppression_dirs","independent_head_suppression","shared_directional_router","late_fixed_pruner","domain_adaptive_then_fixed","oracle_directional_router"}; vector<Row> rows; map<string,int>winners,nonoracle; for(auto&r:regs){vector<Row> cand; for(auto&m:methods)cand.push_back(eval(r,m)); double best=1e9; for(auto&x:cand)best=min(best,x.score); for(auto&x:cand)x.regret=max(0.0,x.score-best); auto b=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); winners[b->method]++; auto no=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){if(a.method=="oracle_directional_router")return false; if(b.method=="oracle_directional_router")return true; return a.score<b.score;}); nonoracle[no->method]++; rows.insert(rows.end(),cand.begin(),cand.end());}
 ofstream f(out); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0033\",\n  \"probe\": \"directional_suppression_router\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:winners){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:nonoracle){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Shared suppression directions are most useful when coordination, not individual head capacity, is the bottleneck; rare directions still need explorer or fallback behavior.\",\n    \"screen_regret_fields\": [\"leakage\", \"ablation_fragility\", \"rare_miss\", \"regret\", \"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"recall\": "<<r.recall<<", \"leakage\": "<<r.leakage<<", \"coordination\": "<<r.coordination<<", \"ablation_fragility\": "<<r.ablation_fragility<<", \"cost\": "<<r.cost<<", \"rare_miss\": "<<r.rare_miss<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1==rows.size()?"\n":",\n");} f<<"  ]\n}\n";}
